from fractions import Fraction

def det(A):
    n = len(A)
    if n == 0:
        return 1
    M = [[Fraction(x) for x in row] for row in A]
    sign = 1
    for k in range(n - 1):
        if M[k][k] == 0:
            pivot = k + 1
            while pivot < n and M[pivot][k] == 0:
                pivot += 1
            if pivot == n:
                return 0
            M[k], M[pivot] = M[pivot], M[k]
            sign = -sign
        for i in range(k + 1, n):
            if M[i][k] != 0:
                f = M[i][k] / M[k][k]
                for j in range(k, n):
                    M[i][j] -= f * M[k][j]
    prod = Fraction(1)
    for i in range(n):
        prod *= M[i][i]
    return int(sign * prod)

def solve(A):
    return det(A)

